from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable

PLAN_SCHEMA = 'edarsahub.bos-plan.v1'
VALID_RISK = ('R0', 'R1', 'R2', 'R3', 'R4')
VALID_DATA_CLASSIFICATIONS = frozenset({
    'PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'PII', 'FINANCIAL_PRIVATE', 'SECRET'
})


class PlanError(ValueError):
    pass


def _token(value: str, field: str) -> str:
    result = str(value or '').strip()
    if not result:
        raise PlanError(f'{field}_REQUIRED')
    return result


def _tokens(values: Iterable[str], field: str) -> tuple[str, ...]:
    result = tuple(_token(value, field) for value in values)
    if len(result) != len(set(result)):
        raise PlanError(f'{field}_DUPLICATED')
    return result


@dataclass(frozen=True)
class PlanStep:
    id: str
    domain: str
    procedure: str
    required_capabilities: tuple[str, ...] = ()
    required_scopes: tuple[str, ...] = ()
    risk: str = 'R0'
    data_classification: str = 'PUBLIC'
    executor: str = 'worker'
    depends_on: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        object.__setattr__(self, 'id', _token(self.id, 'STEP_ID'))
        object.__setattr__(self, 'domain', _token(self.domain, 'STEP_DOMAIN'))
        object.__setattr__(self, 'procedure', _token(self.procedure, 'STEP_PROCEDURE'))
        object.__setattr__(self, 'executor', _token(self.executor, 'STEP_EXECUTOR'))
        object.__setattr__(self, 'required_capabilities', _tokens(self.required_capabilities, 'STEP_CAPABILITY'))
        object.__setattr__(self, 'required_scopes', _tokens(self.required_scopes, 'STEP_SCOPE'))
        object.__setattr__(self, 'depends_on', _tokens(self.depends_on, 'STEP_DEPENDENCY'))
        if self.risk not in VALID_RISK:
            raise PlanError('STEP_RISK_INVALID')
        if self.data_classification not in VALID_DATA_CLASSIFICATIONS:
            raise PlanError('STEP_DATA_CLASSIFICATION_INVALID')
        if self.id in self.depends_on:
            raise PlanError('STEP_SELF_DEPENDENCY')


@dataclass(frozen=True)
class Plan:
    request_id: str
    steps: tuple[PlanStep, ...]
    schema: str = PLAN_SCHEMA

    def __post_init__(self) -> None:
        object.__setattr__(self, 'request_id', _token(self.request_id, 'REQUEST_ID'))
        object.__setattr__(self, 'steps', tuple(self.steps))
        if self.schema != PLAN_SCHEMA:
            raise PlanError('PLAN_SCHEMA_INVALID')
        if not self.steps:
            raise PlanError('PLAN_STEPS_REQUIRED')
        if not all(isinstance(step, PlanStep) for step in self.steps):
            raise PlanError('PLAN_STEP_INVALID')
        ids = tuple(step.id for step in self.steps)
        if len(ids) != len(set(ids)):
            raise PlanError('PLAN_STEP_DUPLICATED')
        known = set(ids)
        for step in self.steps:
            missing = set(step.depends_on) - known
            if missing:
                raise PlanError('PLAN_DEPENDENCY_NOT_FOUND')
        self._validate_acyclic()

    def _validate_acyclic(self) -> None:
        dependencies = {step.id: set(step.depends_on) for step in self.steps}
        ready = sorted(step_id for step_id, deps in dependencies.items() if not deps)
        visited: list[str] = []
        while ready:
            current = ready.pop(0)
            visited.append(current)
            for step_id in sorted(dependencies):
                if current in dependencies[step_id]:
                    dependencies[step_id].remove(current)
                    if not dependencies[step_id] and step_id not in visited and step_id not in ready:
                        ready.append(step_id)
                        ready.sort()
        if len(visited) != len(dependencies):
            raise PlanError('PLAN_CYCLE_DETECTED')

    def topological_steps(self) -> tuple[PlanStep, ...]:
        by_id = {step.id: step for step in self.steps}
        dependencies = {step.id: set(step.depends_on) for step in self.steps}
        ready = sorted(step_id for step_id, deps in dependencies.items() if not deps)
        ordered: list[PlanStep] = []
        while ready:
            current = ready.pop(0)
            ordered.append(by_id[current])
            for step_id in sorted(dependencies):
                if current in dependencies[step_id]:
                    dependencies[step_id].remove(current)
                    if not dependencies[step_id] and all(item.id != step_id for item in ordered) and step_id not in ready:
                        ready.append(step_id)
                        ready.sort()
        return tuple(ordered)


class Planner:
    def build(self, request_id: str, steps: Iterable[PlanStep]) -> Plan:
        return Plan(request_id=request_id, steps=tuple(steps))

from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable

from .planner import PlanStep, VALID_RISK
from .registry import AgentSpec, RegistryError, SkillSpec

RISK_RANK = {risk: index for index, risk in enumerate(VALID_RISK)}


class RouteError(ValueError):
    pass


@dataclass(frozen=True)
class RouteDecision:
    step_id: str
    agent_id: str
    agent_version: str
    skill_id: str
    skill_version: str
    executor: str


def _eligible_skill(step: PlanStep, skill: SkillSpec) -> bool:
    return (
        skill.lifecycle == 'APPROVED'
        and skill.adoption != 'BLOCKED'
        and skill.domain == step.domain
        and skill.id == step.procedure
        and set(step.required_capabilities).issubset(skill.required_capabilities)
        and set(step.required_scopes).issubset(skill.allowed_scopes)
        and RISK_RANK[step.risk] <= RISK_RANK[skill.max_risk]
        and step.data_classification in skill.allowed_data_classifications
        and step.executor in skill.allowed_executors
    )


def _eligible_agent(step: PlanStep, skill: SkillSpec, agent: AgentSpec) -> bool:
    return (
        agent.status == 'APPROVED'
        and step.domain in agent.domains
        and skill.id in agent.allowed_skills
        and set(step.required_capabilities).issubset(agent.capability_ceiling)
        and set(step.required_scopes).issubset(agent.scope_ceiling)
        and RISK_RANK[step.risk] <= RISK_RANK[agent.max_risk]
        and step.data_classification in agent.allowed_data_classifications
    )


def _privilege_score(step: PlanStep, skill: SkillSpec, agent: AgentSpec) -> tuple[int, int, int, int, int, str, str, str, str]:
    return (
        RISK_RANK[agent.max_risk],
        len(agent.capability_ceiling),
        len(agent.scope_ceiling),
        RISK_RANK[skill.max_risk],
        len(skill.allowed_scopes) + len(skill.required_capabilities),
        agent.id,
        agent.version,
        skill.id,
        skill.version,
    )


class Router:
    def route(
        self,
        step: PlanStep,
        agents: Iterable[AgentSpec],
        skills: Iterable[SkillSpec],
    ) -> RouteDecision:
        if not isinstance(step, PlanStep):
            raise RouteError('PLAN_STEP_REQUIRED')
        agents = tuple(agents)
        skills = tuple(skills)
        if not all(isinstance(agent, AgentSpec) for agent in agents):
            raise RouteError('AGENT_SPEC_REQUIRED')
        if not all(isinstance(skill, SkillSpec) for skill in skills):
            raise RouteError('SKILL_SPEC_REQUIRED')

        candidates: list[tuple[tuple[int, int, int, int, int, str, str, str, str], AgentSpec, SkillSpec]] = []
        for skill in skills:
            if not _eligible_skill(step, skill):
                continue
            for agent in agents:
                if _eligible_agent(step, skill, agent):
                    candidates.append((_privilege_score(step, skill, agent), agent, skill))

        if not candidates:
            raise RouteError('NO_ELIGIBLE_ROUTE')

        _, agent, skill = min(candidates, key=lambda candidate: candidate[0])
        return RouteDecision(
            step_id=step.id,
            agent_id=agent.id,
            agent_version=agent.version,
            skill_id=skill.id,
            skill_version=skill.version,
            executor=step.executor,
        )
